L["Konstrukt-Pilot einsetzen. Seelen mit AoE wegräumen."] = "Coloquem o piloto no construto. Limpem as almas com AoE."
L["Socrethar"] = "Socrethar"
L["Totenkopf und Kreuz auf die Dominatoren."] = "Caveira e X nos Dominadores."
L["Tyrannin Velhari + Uralter Vollstrecker, Uralter Herold, Uralter Herrscher"] = "Tirana Velhari + Executor Ancestral, Arauto Ancestral, Soberano Ancestral"
